import React, { useEffect, useState } from 'react';
import axios from 'axios';

const Dashboard = () => {
  const [user, setUser] = useState(null);
  const [repos, setRepos] = useState([]);

  useEffect(() => {
    axios.get('http://localhost:5000/api/user', { withCredentials: true })
      .then((res) => setUser(res.data.user))
      .catch(() => window.location.href = '/');
  }, []);

  useEffect(() => {
    axios.get('http://localhost:5000/api/github/repos', { withCredentials: true })
      .then((res) => setRepos(res.data))
      .catch((err) => console.error('Repo fetch failed:', err));
  }, []);

  if (!user) return <p>Loading...</p>;

  return (
    <div style={{ padding: '2rem' }}>
      <h2>Welcome, {user.displayName}</h2>
      <p>Email: {user.emails?.[0]?.value}</p>
      <p>Username: {user.username}</p>
      <img src={user.photos?.[0]?.value} alt="Avatar" width={80} />

      <h3>Your Repositories:</h3>
      <ul>
        {repos.map(repo => (
          <li key={repo.full_name}>
            <strong>{repo.name}</strong> | ⭐ {repo.stars} | Branch: {repo.default_branch}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default Dashboard;
